arguments.prompt:
You are working in /tmp/sv-3496d0e53748479e9573573949a16c4a/ShipmentTracker which is a Blazor Web App solution with Auto interactivity (Server + WebAssembly) and Individual accounts auth. It has two projects:
- ShipmentTracker (server) 
- ShipmentTracker.Client (WASM client)

The app is for a logistics company to track shipments. Requirements:
- Dispatchers view a list of shipments with status and destination
- Customers check their shipment status and estimated delivery
- Users are worldwide — the Auto render mode handles fast first load (Server) then snappy client-side (WASM)
- Every page involves interactive controls
- Staff and customers authenticate with individual accounts
- Role-based auth: "Dispatcher" role for staff, "Customer" role for customers

Please implement the following:

## 1. Shared Models (in ShipmentTracker.Client project since both projects reference it)

Create `ShipmentTracker.Client/Models/Shipment.cs`:
```csharp
namespace ShipmentTracker.Client.Models;

public class ShipmentDto
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Delayed
}
```

## 2. Server-side Entity and DbContext

Create `ShipmentTracker/Data/Shipment.cs`:
```csharp
using System.ComponentModel.DataAnnotations;

namespace ShipmentTracker.Data;

public class Shipment
{
    public int Id { get; set; }

    [Required, MaxLength(20)]
    public string TrackingNumber { get; set; } = string.Empty;

    [Required, MaxLength(200)]
    public string Origin { get; set; } = string.Empty;

    [Required, MaxLength(200)]
    public string Destination { get; set; } = string.Empty;

    public int Status { get; set; }

    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }

    [Required]
    public string CustomerUserId { get; set; } = string.Empty;

    [MaxLength(500)]
    public string Description { get; set; } = string.Empty;
}
```

Update `ShipmentTracker/Data/ApplicationDbContext.cs` to add:
```csharp
using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;

namespace ShipmentTracker.Data;

public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> options) : IdentityDbContext<ApplicationUser>(options)
{
    public DbSet<Shipment> Shipments => Set<Shipment>();
}
```

## 3. API Endpoints

Create `ShipmentTracker/Endpoints/ShipmentEndpoints.cs`:
```csharp
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Data;
using System.Security.Claims;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("/api/shipments").RequireAuthorization();

        // Get all shipments (dispatchers only)
        group.MapGet("/", async (ApplicationDbContext db, ClaimsPrincipal user) =>
        {
            if (!user.IsInRole("Dispatcher"))
                return Results.Forbid();

            var shipments = await db.Shipments
                .OrderByDescending(s => s.ShippedDate)
                .Select(s => new ShipmentDto
                {
                    Id = s.Id,
                    TrackingNumber = s.TrackingNumber,
                    Origin = s.Origin,
                    Destination = s.Destination,
                    Status = (ShipmentStatus)s.Status,
                    ShippedDate = s.ShippedDate,
                    EstimatedDelivery = s.EstimatedDelivery,
                    CustomerEmail = s.CustomerUserId,
                    Description = s.Description
                })
                .ToListAsync();

            return Results.Ok(shipments);
        });

        // Get shipments for the current customer
        group.MapGet("/my", async (ApplicationDbContext db, ClaimsPrincipal user) =>
        {
            var userId = user.FindFirstValue(ClaimTypes.NameIdentifier);
            if (userId is null) return Results.Unauthorized();

            var shipments = await db.Shipments
                .Where(s => s.CustomerUserId == userId)
                .OrderByDescending(s => s.ShippedDate)
                .Select(s => new ShipmentDto
                {
                    Id = s.Id,
                    TrackingNumber = s.TrackingNumber,
                    Origin = s.Origin,
                    Destination = s.Destination,
                    Status = (ShipmentStatus)s.Status,
                    ShippedDate = s.ShippedDate,
                    EstimatedDelivery = s.EstimatedDelivery,
                    CustomerEmail = "",
                    Description = s.Description
                })
                .ToListAsync();

            return Results.Ok(shipments);
        });

        // Track by tracking number (customer)
        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db, ClaimsPrincipal user) =>
        {
            var userId = user.FindFirstValue(ClaimTypes.NameIdentifier);
            var shipment = await db.Shipments
                .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);

            if (shipment is null) return Results.NotFound();

            // Customers can only see their own shipments; dispatchers can see all
            if (!user.IsInRole("Dispatcher") && shipment.CustomerUserId != userId)
                return Results.Forbid();

            return Results.Ok(new ShipmentDto
            {
                Id = shipment.Id,
                TrackingNumber = shipment.TrackingNumber,
                Origin = shipment.Origin,
                Destination = shipment.Destination,
                Status = (ShipmentStatus)shipment.Status,
                ShippedDate = shipment.ShippedDate,
                EstimatedDelivery = shipment.EstimatedDelivery,
                CustomerEmail = shipment.CustomerUserId,
                Description = shipment.Description
            });
        });

        // Create shipment (dispatcher only)
        group.MapPost("/", async (ShipmentDto dto, ApplicationDbContext db, ClaimsPrincipal user) =>
        {
            if (!user.IsInRole("Dispatcher"))
                return Results.Forbid();

            var shipment = new Shipment
            {
                TrackingNumber = dto.TrackingNumber,
                Origin = dto.Origin,
                Destination = dto.Destination,
                Status = (int)dto.Status,
                ShippedDate = dto.ShippedDate,
                EstimatedDelivery = dto.EstimatedDelivery,
                CustomerUserId = dto.CustomerEmail,
                Description = dto.Description
            };

            db.Shipments.Add(shipment);
            await db.SaveChangesAsync();

            dto.Id = shipment.Id;
            return Results.Created($"/api/shipments/{shipment.Id}", dto);
        });

        // Update shipment status (dispatcher only)
        group.MapPut("/{id}", async (int id, ShipmentDto dto, ApplicationDbContext db, ClaimsPrincipal user) =>
        {
            if (!user.IsInRole("Dispatcher"))
                return Results.Forbid();

            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();

            shipment.Status = (int)dto.Status;
            shipment.Destination = dto.Destination;
            shipment.EstimatedDelivery = dto.EstimatedDelivery;
            shipment.Description = dto.Description;

            await db.SaveChangesAsync();
            return Results.Ok(dto);
        });
    }
}
```

## 4. Register endpoints and add roles/seed data in Program.cs

Update `ShipmentTracker/Program.cs` — add at the end before `app.Run();`:
```csharp
app.MapShipmentEndpoints();
```

Also add `using ShipmentTracker.Endpoints;` at the top.

Also add after `builder.Services.AddSingleton<IEmailSender<ApplicationUser>, IdentityNoOpEmailSender>();`:
```csharp
builder.Services.AddAuthorizationBuilder()
    .AddPolicy("DispatcherOnly", policy => policy.RequireRole("Dispatcher"))
    .AddPolicy("CustomerOnly", policy => policy.RequireRole("Customer"));
```

And add role seeding. After `var app = builder.Build();` add:
```csharp
// Seed roles
using (var scope = app.Services.CreateScope())
{
    var roleManager = scope.ServiceProvider.GetRequiredService<RoleManager<IdentityRole>>();
    string[] roles = ["Dispatcher", "Customer"];
    foreach (var role in roles)
    {
        if (!await roleManager.RoleExistsAsync(role))
        {
            await roleManager.CreateAsync(new IdentityRole(role));
        }
    }
}
```

Make sure to add `.AddRoles<IdentityRole>()` to the identity configuration chain (after `.AddIdentityCore<ApplicationUser>(...)`).

