@code {
    private List<ShipmentDto>? shipments;
    private ShipmentDto newShipment = new() { ShippedDate = DateTime.Today, EstimatedDelivery = DateTime.Today.AddDays(5) };
    private bool showCreateForm;
    private string filterText = string.Empty;
    private string sortColumn = "TrackingNumber";
    private bool sortAscending = true;
    private string message = string.Empty;

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        try
        {
            shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments");
        }
        catch (Exception ex)
        {
            message = $"Error loading shipments: {ex.Message}";
        }
    }

    private IEnumerable<ShipmentDto> FilteredShipments =>
        (shipments ?? new())
        .Where(s => string.IsNullOrEmpty(filterText) ||
            s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.Status.ToString().Contains(filterText, StringComparison.OrdinalIgnoreCase))
        .OrderBy(s => sortColumn switch
        {
            "TrackingNumber" => s.TrackingNumber as object,
            "Destination" => s.Destination,
            "Status" => s.Status.ToString(),
            "EstimatedDelivery" => s.EstimatedDelivery,
            _ => s.TrackingNumber
        }, sortAscending ? Comparer<object>.Default : Comparer<object>.Create((a, b) => Comparer<object>.Default.Compare(b, a)));

    private void SortBy(string column)
    {
        if (sortColumn == column)
            sortAscending = !sortAscending;
        else
        {
            sortColumn = column;
            sortAscending = true;
        }
    }

    private void ShowCreateForm() => showCreateForm = true;
    private void CancelCreate() => showCreateForm = false;

    private async Task CreateShipment()
    {
        var response = await Http.PostAsJsonAsync("/api/shipments", newShipment);
        if (response.IsSuccessStatusCode)
        {
            message = $"Shipment {newShipment.TrackingNumber} created successfully.";
            showCreateForm = false;
            newShipment = new() { ShippedDate = DateTime.Today, EstimatedDelivery = DateTime.Today.AddDays(5) };
            await LoadShipments();
        }
        else
        {
            message = "Failed to create shipment.";
        }
    }

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (int.TryParse(e.Value?.ToString(), out var statusValue))
        {
            shipment.Status = (ShipmentStatus)statusValue;
