@page "/dispatcher"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@attribute [Authorize(Roles = "Dispatcher")]
@inject HttpClient Http

<PageTitle>Dispatcher Dashboard</PageTitle>

<h1>Shipment Management</h1>

<div class="mb-3">
    <button class="btn btn-primary" @onclick="ShowCreateForm">
        <span class="oi oi-plus"></span> New Shipment
    </button>
    <button class="btn btn-secondary ms-2" @onclick="LoadShipments">
        <span class="oi oi-reload"></span> Refresh
    </button>
</div>

@if (showCreateForm)
{
    <div class="card mb-4">
        <div class="card-header">Create New Shipment</div>
        <div class="card-body">
            <EditForm Model="newShipment" OnValidSubmit="CreateShipment" FormName="CreateShipment">
                <DataAnnotationsValidator />
                <div class="row">
                    <div class="col-md-6 mb-2">
                        <label class="form-label">Tracking Number</label>
                        <InputText class="form-control" @bind-Value="newShipment.TrackingNumber" />
                    </div>
                    <div class="col-md-6 mb-2">
                        <label class="form-label">Customer User ID</label>
                        <InputText class="form-control" @bind-Value="newShipment.CustomerEmail" />
                    </div>
                    <div class="col-md-6 mb-2">
                        <label class="form-label">Origin</label>
                        <InputText class="form-control" @bind-Value="newShipment.Origin" />
                    </div>
                    <div class="col-md-6 mb-2">
                        <label class="form-label">Destination</label>
                        <InputText class="form-control" @bind-Value="newShipment.Destination" />
                    </div>
                    <div class="col-md-6 mb-2">
                        <label class="form-label">Shipped Date</label>
                        <InputDate class="form-control" @bind-Value="newShipment.ShippedDate" />
                    </div>
                    <div class="col-md-6 mb-2">
                        <label class="form-label">Estimated Delivery</label>
                        <InputDate class="form-control" @bind-Value="newShipment.EstimatedDelivery" />
                    </div>
                    <div class="col-12 mb-2">
                        <label class="form-label">Description</label>
                        <InputText class="form-control" @bind-Value="newShipment.Description" />
                    </div>
                    <div class="col-md-6 mb-2">
                        <label class="form-label">Status</label>
                        <InputSelect class="form-select" @bind-Value="newShipment.Status">
                            @foreach (var status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@status">@status</option>
                            }
                        </InputSelect>
                    </div>
                </div>
                <button type="submit" class="btn btn-success mt-2">Create</button>
                <button type="button" class="btn btn-outline-secondary mt-2 ms-2" @onclick="CancelCreate">Cancel</button>
            </EditForm>
        </div>
    </div>
}

@if (shipments == null)
{
    <p><em>Loading shipments...</em></p>
}
else if (!shipments.Any())
{
    <p>No shipments found.</p>
}
else
{
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Filter by tracking number, destination, or status..."
               @bind="filterText" @bind:event="oninput" />
    </div>

    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th @onclick='() => SortBy("TrackingNumber")' style="cursor:pointer">Tracking # ↕</th>
                    <th @onclick='() => SortBy("Destination")' style="cursor:pointer">Destination ↕</th>
                    <th @onclick='() => SortBy("Status")' style="cursor:pointer">Status ↕</th>
                    <th>Origin</th>
                    <th @onclick='() => SortBy("EstimatedDelivery")' style="cursor:pointer">Est. Delivery ↕</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var shipment in FilteredShipments)
                {
                    <tr>
                        <td>@shipment.TrackingNumber</td>
                        <td>@shipment.Destination</td>
                        <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                        <td>@shipment.Origin</td>
                        <td>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                        <td>
                            <select class="form-select form-select-sm d-inline-block w-auto"
                                    value="@((int)shipment.Status)"
                                    @onchange="(e) => UpdateStatus(shipment, e)">
                                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                {
                                    <option value="@((int)status)">@status</option>
                                }
                            </select>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
    <p class="text-muted">Showing @FilteredShipments.Count() of @shipments.Count shipments</p>
}

@if (!string.IsNullOrEmpty(message))
{
    <div class="alert alert-info alert-dismissible mt-3">
        @message
        <button type="button" class="btn-close" @onclick="() => message = string.Empty"></button>
    </div>
}

@code {
    private List<ShipmentDto>? shipments;
    private ShipmentDto newShipment = new() { ShippedDate = DateTime.Today, EstimatedDelivery = DateTime.Today.AddDays(5) };
    private bool showCreateForm;
    private string filterText = string.Empty;
    private string sortColumn = "TrackingNumber";
    private bool sortAscending = true;
    private string message = string.Empty;

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        try
        {
            shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments");
        }
        catch (Exception ex)
        {
            message = $"Error loading shipments: {ex.Message}";
        }
    }

    private IEnumerable<ShipmentDto> FilteredShipments =>
        (shipments ?? new())
        .Where(s => string.IsNullOrEmpty(filterText) ||
            s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.Status.ToString().Contains(filterText, StringComparison.OrdinalIgnoreCase))
        .OrderBy(s => sortColumn switch
        {
            "TrackingNumber" => s.TrackingNumber as object,
            "Destination" => s.Destination,
            "Status" => s.Status.ToString(),
            "EstimatedDelivery" => s.EstimatedDelivery,
            _ => s.TrackingNumber
        }, sortAscending ? Comparer<object>.Default : Comparer<object>.Create((a, b) => Comparer<object>.Default.Compare(b, a)));

    private void SortBy(string column)
    {
        if (sortColumn == column)
            sortAscending = !sortAscending;
        else
        {
            sortColumn = column;
            sortAscending = true;
        }
    }

    private void ShowCreateForm() => showCreateForm = true;
    private void CancelCreate() => showCreateForm = false;

    private async Task CreateShipment()
    {
        var response = await Http.PostAsJsonAsync("/api/shipments", newShipment);
        if (response.IsSuccessStatusCode)
        {
            message = $"Shipment {newShipment.TrackingNumber} created successfully.";
            showCreateForm = false;
            newShipment = new() { ShippedDate = DateTime.Today, EstimatedDelivery = DateTime.Today.AddDays(5) };
            await LoadShipments();
        }
        else
        {
            message = "Failed to create shipment.";
        }
    }

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (int.TryParse(e.Value?.ToString(), out var statusValue))
        {
            shipment.Status = (ShipmentStatus)statusValue;
            var response = await Http.PutAsJsonAsync($"/api/shipments/{shipment.Id}", shipment);
            if (response.IsSuccessStatusCode)
                message = $"Shipment {shipment.TrackingNumber} updated to {shipment.Status}.";
            else
                message = "Failed to update shipment status.";
        }
    }

    private string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@attribute [Authorize]
@inject HttpClient Http

<PageTitle>Track Shipment</PageTitle>

<h1>Track Your Shipment</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number..."
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="TrackByNumber">
                <span class="oi oi-magnifying-glass"></span> Track
            </button>
        </div>
    </div>
</div>

@if (isLoading)
{
    <div class="spinner-border text-primary" role="status">
        <span class="visually-hidden">Loading...</span>
    </div>
}

@if (trackedShipment is not null)
{
    <div class="card mb-4">
        <div class="card-header bg-primary text-white">
            <h5 class="mb-0">Shipment @trackedShipment.TrackingNumber</h5>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <p><strong>From:</strong> @trackedShipment.Origin</p>
                    <p><strong>To:</strong> @trackedShipment.Destination</p>
                    <p><strong>Description:</strong> @trackedShipment.Description</p>
                </div>
                <div class="col-md-6">
                    <p><strong>Status:</strong> <span class="badge @GetStatusBadgeClass(trackedShipment.Status) fs-6">@trackedShipment.Status</span></p>
                    <p><strong>Shipped:</strong> @trackedShipment.ShippedDate.ToString("MMMM dd, yyyy")</p>
                    <p><strong>Estimated Delivery:</strong> <span class="fw-bold text-primary">@trackedShipment.EstimatedDelivery.ToString("MMMM dd, yyyy")</span></p>
                </div>
            </div>

            <!-- Progress visualization -->
            <div class="mt-3">
                <h6>Shipment Progress</h6>
                <div class="progress" style="height: 30px;">
                    <div class="progress-bar @GetProgressBarClass(trackedShipment.Status)"
                         role="progressbar"
                         style="width: @(GetProgressPercent(trackedShipment.Status))%"
                         aria-valuenow="@GetProgressPercent(trackedShipment.Status)"
                         aria-valuemin="0" aria-valuemax="100">
                        @trackedShipment.Status
                    </div>
                </div>
            </div>
        </div>
    </div>
}

<h3 class="mt-4">My Shipments</h3>

@if (myShipments == null)
{
    <p><em>Loading your shipments...</em></p>
}
else if (!myShipments.Any())
{
    <p>You have no shipments.</p>
}
else
{
    <div class="row">
        @foreach (var shipment in myShipments)
        {
            <div class="col-md-6 col-lg-4 mb-3">
                <div class="card h-100 @(shipment.Status == ShipmentStatus.Delivered ? "border-success" : shipment.Status == ShipmentStatus.Delayed ? "border-danger" : "")">
                    <div class="card-body">
                        <h6 class="card-title">@shipment.TrackingNumber</h6>
                        <p class="card-text mb-1"><small class="text-muted">@shipment.Origin → @shipment.Destination</small></p>
                        <p class="card-text mb-1">
                            <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span>
                        </p>
                        <p class="card-text"><small><strong>ETA:</strong> @shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</small></p>
                    </div>
                    <div class="card-footer">
                        <button class="btn btn-sm btn-outline-primary" @onclick="() => ViewDetails(shipment)">View Details</button>
                    </div>
                </div>
            </div>
        }
    </div>
}

@if (!string.IsNullOrEmpty(errorMessage))
{
    <div class="alert alert-warning alert-dismissible mt-3">
        @errorMessage
        <button type="button" class="btn-close" @onclick="() => errorMessage = string.Empty"></button>
    </div>
}

@code {
    private List<ShipmentDto>? myShipments;
    private ShipmentDto? trackedShipment;
    private string trackingNumber = string.Empty;
    private string errorMessage = string.Empty;
    private bool isLoading;

    protected override async Task OnInitializedAsync()
    {
        await LoadMyShipments();
    }

    private async Task LoadMyShipments()
    {
        try
        {
            myShipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments/my");
        }
        catch (Exception ex)
        {
            errorMessage = $"Error loading shipments: {ex.Message}";
        }
    }

    private async Task TrackByNumber()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        isLoading = true;
        errorMessage = string.Empty;
        trackedShipment = null;

        try
        {
            var response = await Http.GetAsync($"/api/shipments/track/{trackingNumber.Trim()}");
            if (response.IsSuccessStatusCode)
            {
                trackedShipment = await response.Content.ReadFromJsonAsync<ShipmentDto>();
            }
            else if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
            {
                errorMessage = $"No shipment found with tracking number '{trackingNumber}'.";
            }
            else
            {
                errorMessage = "Unable to retrieve shipment information.";
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Error: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackByNumber();
    }

    private void ViewDetails(ShipmentDto shipment)
    {
        trackedShipment = shipment;
    }

    private int GetProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 30,
        ShipmentStatus.InTransit => 55,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Delayed => 55,
        _ => 0
    };

    private string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger progress-bar-striped progress-bar-animated",
        ShipmentStatus.OutForDelivery => "bg-warning",
        _ => "bg-primary progress-bar-striped progress-bar-animated"
    };

