Create `ShipmentTracker/Data/SeedData.cs`:
```csharp
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;

namespace ShipmentTracker.Data;

public static class SeedData
{
    public static async Task SeedShipmentsAsync(IServiceProvider serviceProvider)
    {
        using var scope = serviceProvider.CreateScope();
        var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();

        if (await db.Shipments.AnyAsync()) return;

        var shipments = new List<Shipment>
        {
            new() { TrackingNumber = "TRK-001-2024", Origin = "New York, NY", Destination = "Los Angeles, CA", Status = 2, ShippedDate = DateTime.Today.AddDays(-3), EstimatedDelivery = DateTime.Today.AddDays(2), CustomerUserId = "demo-customer", Description = "Electronics - Fragile" },
            new() { TrackingNumber = "TRK-002-2024", Origin = "Chicago, IL", Destination = "Miami, FL", Status = 1, ShippedDate = DateTime.Today.AddDays(-1), EstimatedDelivery = DateTime.Today.AddDays(4), CustomerUserId = "demo-customer", Description = "Furniture" },
            new() { TrackingNumber = "TRK-003-2024", Origin = "Seattle, WA", Destination = "Denver, CO", Status = 4, ShippedDate = DateTime.Today.AddDays(-7), EstimatedDelivery = DateTime.Today.AddDays(-1), CustomerUserId = "demo-customer", Description = "Books and Media" },
            new() { TrackingNumber = "TRK-004-2024", Origin = "Boston, MA", Destination = "Houston, TX", Status = 3, ShippedDate = DateTime.Today.AddDays(-2), EstimatedDelivery = DateTime.Today, CustomerUserId = "demo-customer", Description = "Clothing" },
            new() { TrackingNumber = "TRK-005-2024", Origin = "San Francisco, CA", Destination = "Phoenix, AZ", Status = 5, ShippedDate = DateTime.Today.AddDays(-4), EstimatedDelivery = DateTime.Today.AddDays(3), CustomerUserId = "demo-customer", Description = "Industrial Parts" },
